from pathlib import Path
import json,hashlib
P=Path(__file__).resolve().parent;old=P/'benchmark-v2';B=P/'benchmark-v3';B.mkdir(exist_ok=False)
q=json.loads((old/'questions.json').read_text());k=json.loads((old/'answer-key.json').read_text());q['benchmark_version']=k['benchmark_version']='v3-expanded-designer-clarification'
rows=[('Can Sinbad discard one of the six non-Home Voyage cards to BOOST maneuver movement and thereby put it in the discard pile? How does Voyage Home differ, and is an absent BOOST value simply a printed zero?', 'No; six non-Home Voyages have no BOOST value and cannot be used as BOOST payment | Voyage Home has printed BOOST 1 and may pay for BOOST | Missing value is not a printed zero', ['sinbad-action-cards.png r1c5;r2c5–6;r3c1–4; rulebook p10; Justin Jacobson BGG thread2294803 2019-10-17 primary post'], 'Previously untested absent-BOOST payment prohibition and Home exception'),('BIG Alice attacks with Momentous Shift after starting the turn in another space; defender uses Feint (value 2). What does Feint cancel, does it cancel Alice’s character-card bonus, and what are her attack value and attack damage?', 'Feint cancels Momentous Shift effect so no replacement value 5 | Alice character ability is not an effect on the attack card and remains | Alice attack value 3+2=5; against defense 2 deals 3 attack damage', ['alice-character.png; alice-action-cards.png r3c5–6;r5c1–3; rulebook p12'], 'Card-effects cancellation scope contrasted with character ability'),('Sinbad begins a maneuver with no Voyages in his discard pile, draws normally, then discards Voyage Home to BOOST before moving. What is the movement allowance for Sinbad and Porter in this maneuver, and does that discard resolve Home’s after-combat retrieval effect?', 'After discard Home is in discard pile: move2 + printed BOOST1 + Voyage-count1 =4 for each fighter | Discarding to BOOST ignores Home card effects so no after-combat retrieval', ['sinbad-character.png; sinbad-action-cards.png r1c5; rulebook p9–10'], 'Discard-before-movement timing changes current Voyage count; BOOST ignores effects')]
for question,a,refs,novelty in rows:
 id=f'Q{len(q["questions"])+1:02d}';q['questions'].append({'id':id,'question':question});k['answers'].append({'id':id,'expected_answer':a.replace(' | ','; '),'required_facts':a.split(' | '),'contextual_background':[],'source_refs':refs})
for name,data in [('questions.json',q),('answer-key.json',k)]: (B/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
(B/'scope-map.json').write_text(json.dumps({'benchmark':q['benchmark_version'],'policy':'Score actual requested clauses only. Contextual expected-answer background is not an additional required fact. No global source-gap score caps.','questions':[{'id':x['id'],'asked_clauses':x['question'],'required_answer_facts':a['required_facts'],'contextual_key_background':a['contextual_background'],'source_refs':a['source_refs']} for x,a in zip(q['questions'],k['answers'])]},ensure_ascii=False,indent=2)+'\n')
(B/'question-bank.md').write_text('# Unmatched expanded fixed bank v3\n\n'+ '\n\n'.join(f"## {x['id']}\n\n{x['question']}\n\n**Expected:** {a['expected_answer']}\n\n**Source:** {'; '.join(a['source_refs'])}" for x,a in zip(q['questions'],k['answers']))+'\n')
(B/'input-manifest.json').write_text(json.dumps({'preserves_v1_and_v2':q['questions'][:58]==json.loads((old/'questions.json').read_text())['questions'] and k['answers'][:58]==json.loads((old/'answer-key.json').read_text())['answers'],'hashes':{n:hashlib.sha256((B/n).read_bytes()).hexdigest() for n in ['questions.json','answer-key.json','scope-map.json','question-bank.md']}},indent=2)+'\n')
print('v3',len(q['questions']))
